               'SELAFA', 'SELCA', 'SELURL', 'SEL', 'SCP', 'SCM', 'SCOP', 'SCIC', 'SEM', 'SEML', 'SAEM', 'SPL',
               'GIE', 'GAEC', 'EARL', 'EI', 'EIRL', 'EPIC', 'SASP', 'SCEA', 'SICA', 'SE']
$$;
